import{_ as a,o as n,c as p,a2 as t}from"./chunks/framework.C4u7U0Dw.js";const d=JSON.parse('{"title":"行政与文秘提示词模板","description":"行政与文秘岗位的 5 条提示词模板：会议筹备、通知公告、接待方案、日程协调、汇报材料。","frontmatter":{"title":"行政与文秘提示词模板","description":"行政与文秘岗位的 5 条提示词模板：会议筹备、通知公告、接待方案、日程协调、汇报材料。"},"headers":[],"relativePath":"community/prompts/行政与文秘.md","filePath":"community/prompts/行政与文秘.md"}'),e={name:"community/prompts/行政与文秘.md"};function l(i,s,o,c,r,u){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="📋-行政与文秘-·-5-条提示词模板" tabindex="-1">📋 行政与文秘 · 5 条提示词模板 <a class="header-anchor" href="#📋-行政与文秘-·-5-条提示词模板" aria-label="Permalink to &quot;📋 行政与文秘 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>这行的价值不在&quot;会写字&quot;，在**&quot;不出错&quot;**。 会开得顺、通知没人问第二遍、接待不掉链子——这些才是你的成绩。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在【什么单位 / 什么部门】，现在要办【什么事】。</span></span>
<span class="line"><span>帮我产出【清单 / 通知 / 方案】，形式【…】。</span></span>
<span class="line"><span>按我们单位的实际情况来（人数、场地、惯例），不确定的地方标出来让我确认。</span></span></code></pre></div><hr><h2 id="_1-·-会议筹备清单-会前-会中-会后" tabindex="-1">1 · 会议筹备清单（会前 / 会中 / 会后） <a class="header-anchor" href="#_1-·-会议筹备清单-会前-会中-会后" aria-label="Permalink to &quot;1 · 会议筹备清单（会前 / 会中 / 会后）&quot;">​</a></h2><p><strong>什么时候用</strong>：要办一个会，参会人、材料、场地、设备……怕漏掉哪一项。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>会议情况：</span></span>
<span class="line"><span>- 主题与目的：【…】</span></span>
<span class="line"><span>- 时间地点：【…】，场地条件：【…（多大、有没有投影、网络）】</span></span>
<span class="line"><span>- 参会人：【人数 / 层级 / 有没有外部人员 / 要不要签到】</span></span>
<span class="line"><span>- 主持人与发言人：【…】</span></span>
<span class="line"><span>- 需要产出什么：【纪要 / 决议 / 签字文件 / 拍照留档】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我出一份筹备清单，分成四段：</span></span>
<span class="line"><span>① 会前（提前 3 天 / 1 天 / 当天各要做什么，含通知发送时间）</span></span>
<span class="line"><span>② 会中（谁做什么：签到、记录、设备、茶水、拍照）</span></span>
<span class="line"><span>③ 会后（纪要时限、文件归档、跟催待办）</span></span>
<span class="line"><span>④ 应急预案（设备坏、人不来、超时、争议话题）</span></span>
<span class="line"><span>每一项都标&quot;谁负责 + 怎么算完成&quot;。</span></span>
<span class="line"><span>规矩：不要写&quot;提前做好准备工作&quot;这种废话，每一条都必须是能打勾的动作。</span></span></code></pre></div><p><strong>它给你</strong>：一份能打勾的清单 + 应急预案。</p><hr><h2 id="_2-·-通知-公告-对内、对外两个版本" tabindex="-1">2 · 通知 / 公告（对内、对外两个版本） <a class="header-anchor" href="#_2-·-通知-公告-对内、对外两个版本" aria-label="Permalink to &quot;2 · 通知 / 公告（对内、对外两个版本）&quot;">​</a></h2><p><strong>什么时候用</strong>：一件事要通知，你要考虑：领导怎么看、同事会不会有意见、外部人会不会误解。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>要通知的事：【…】</span></span>
<span class="line"><span>通知对象：【全体员工 / 某个部门 / 外部单位 / 客户】</span></span>
<span class="line"><span>要解决的问题：【为什么发这个通知】</span></span>
<span class="line"><span>可能的顾虑：【有人会问什么 / 会不会有反弹 / 要不要留口子】</span></span>
<span class="line"><span>执行时间与责任人：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写：</span></span>
<span class="line"><span>① 内部版（发群/发邮件）：标题 + 正文，先说什么事、再说为什么、再说怎么做、最后是谁负责和什么时候。300 字内。</span></span>
<span class="line"><span>② 对外版（发公众号/正式函）：措辞更正式，去掉内部信息（人名、内部流程）。</span></span>
<span class="line"><span>③ 一份&quot;预判问题清单&quot;：发出去后最可能被问的 5 个问题 + 标准答复</span></span>
<span class="line"><span>④ 一句话版（用于口头通知或群公告置顶）</span></span>
<span class="line"><span>规矩：时间、地点、人名一律用我给的；不确定的不写&quot;另行通知&quot;以外的东西。</span></span></code></pre></div><p><strong>它给你</strong>：两版通知 + 预判问答 + 一句话版。</p><hr><h2 id="_3-·-接待方案-来访-检查-参观" tabindex="-1">3 · 接待方案（来访 / 检查 / 参观） <a class="header-anchor" href="#_3-·-接待方案-来访-检查-参观" aria-label="Permalink to &quot;3 · 接待方案（来访 / 检查 / 参观）&quot;">​</a></h2><p><strong>什么时候用</strong>：有外部人员要来，你要安排一整条动线，还要照顾到&quot;面子&quot;和&quot;里子&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>来访情况：【谁 / 几个人 / 什么级别 / 为什么来 / 待多久】</span></span>
<span class="line"><span>我方参与人：【…】，谁主陪：【…】</span></span>
<span class="line"><span>场地与资源：【会议室 / 参观路线 / 车辆 / 餐食 / 纪念品】</span></span>
<span class="line"><span>要达成的目的：【…（例如谈成什么 / 展示什么 / 别出什么岔子）】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我做一份接待方案：</span></span>
<span class="line"><span>① 时间轴（精确到 15 分钟）：接站/门口迎接 → 落座 → 谁先说什么 → 参观动线 → 用餐 → 送别</span></span>
<span class="line"><span>② 每个人的角色分工（谁说话、谁记录、谁拍照、谁控场）</span></span>
<span class="line"><span>③ 一份&quot;该说 / 不该说&quot;清单（涉及敏感话题时的应对）</span></span>
<span class="line"><span>④ 物料清单（席卡、资料袋、水、PPT、备用打印件）</span></span>
<span class="line"><span>⑤ 结束后 24 小时内要做的事（回访、发照片、发纪要）</span></span>
<span class="line"><span>规矩：不编对方的头衔和单位名称；餐食和车辆安排按我给的条件来。</span></span></code></pre></div><p><strong>它给你</strong>：一份精确到分钟的接待方案。</p><hr><h2 id="_4-·-多方日程协调-找一个大家都能来的时间" tabindex="-1">4 · 多方日程协调（找一个大家都能来的时间） <a class="header-anchor" href="#_4-·-多方日程协调-找一个大家都能来的时间" aria-label="Permalink to &quot;4 · 多方日程协调（找一个大家都能来的时间）&quot;">​</a></h2><p><strong>什么时候用</strong>：要凑 6 个人开会，来回问时间问了三轮还没定。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>参会名单与可用时间（尽量写全）：</span></span>
<span class="line"><span>- 张三：【周几有空 / 什么时段不行 / 有没有固定例会】</span></span>
<span class="line"><span>- 李四：【…】</span></span>
<span class="line"><span>（依次）</span></span>
<span class="line"><span>会议时长：【…】，必须参加的人：【…】，可缺席的人：【…】</span></span>
<span class="line"><span>可选场地/线上方式：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 列出所有可行的时段（按&quot;能来的人最多&quot;排序，标出谁缺席）</span></span>
<span class="line"><span>② 给推荐方案（首选 + 备选），并说明每个方案的风险</span></span>
<span class="line"><span>③ 写一条征求时间的消息（一次性把所有选项列出来，让大家回复编号即可，别再来回问）</span></span>
<span class="line"><span>④ 如果实在凑不齐，给我一个&quot;分成两次开&quot;或&quot;先开核心小组&quot;的替代方案</span></span>
<span class="line"><span>规矩：严格按我给的时间约束来，不要替我假设谁&quot;应该有空&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：可行时段表 + 一条能一次问清的消息。</p><hr><h2 id="_5-·-汇报材料-讲话稿要点-不是帮你写空话" tabindex="-1">5 · 汇报材料 / 讲话稿要点（不是帮你写空话） <a class="header-anchor" href="#_5-·-汇报材料-讲话稿要点-不是帮你写空话" aria-label="Permalink to &quot;5 · 汇报材料 / 讲话稿要点（不是帮你写空话）&quot;">​</a></h2><p><strong>什么时候用</strong>：领导要发言、要汇报，你要出材料，但最怕写成一堆正确的废话。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场合：【…】，时长：【…】，听众：【…】</span></span>
<span class="line"><span>必须讲到的实质内容（我来提供的事实）：【1. … 2. … 3. …】</span></span>
<span class="line"><span>希望达成的效果：【…】，要避开的说法：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 先列&quot;听众只关心这 3 件事&quot;（基于听众身份推）</span></span>
<span class="line"><span>② 出一个结构（开场 / 主体 3 点 / 收尾），每点写出&quot;要点 + 支撑事实（用我给的事实）&quot;</span></span>
<span class="line"><span>③ 按这个结构写一版口语稿（适合念，短句，300-600 字）</span></span>
<span class="line"><span>④ 单独给我 5 句可以替换的&quot;不空洞的开头&quot;</span></span>
<span class="line"><span>⑤ 标出稿子里哪些句子是&quot;没信息量的漂亮话&quot;，建议删掉</span></span>
<span class="line"><span>规矩：不许加我未提供的数据、成绩、案例；不许用&quot;高度重视&quot;&quot;全力推进&quot;这类没有具体内容的表述。</span></span></code></pre></div><p><strong>它给你</strong>：一份有实质内容的稿 + 自我审查清单。</p><hr><h2 id="⚠️-这三条比模板更重要" tabindex="-1">⚠️ 这三条比模板更重要 <a class="header-anchor" href="#⚠️-这三条比模板更重要" aria-label="Permalink to &quot;⚠️ 这三条比模板更重要&quot;">​</a></h2><ol><li><strong>AI 很爱写&quot;正确的废话&quot;</strong>：读完很顺，但没有任何信息。<strong>判断标准：每句话能不能反问&quot;具体是多少 / 谁 / 什么时候&quot;。答不上来就删。</strong></li><li><strong>内部信息分级</strong>：对外版材料一定要单独写一份，别拿内部版改了改就发出去（人名、流程、数据最容易漏）。</li><li><strong>时间、人名、头衔必须自己核</strong>：AI 写错的场合和人名，比写错字尴尬得多。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/制造与工厂.html">制造与工厂</a></strong></p>`,34)])])}const g=a(e,[["render",l]]);export{d as __pageData,g as default};
